mapper.select:
SELECT so.id, so.shipping_no, so.provider_id, so.shipping_date, so.estimated_arrival_date, so.shipping_method, so.shipping_route, so.target_region_id, so.package_count, so.total_weight, so.total_amount, so.payment_status, so.shipping_status, so.create_time FROM wms_shipping_order so
so.deleted = 0
AND so.shipping_no LIKE CONCAT('%', #{qo.shippingNo}, '%')
AND so.provider_id = #{qo.providerId}
AND so.shipping_status = #{qo.shippingStatus}
AND so.payment_status = #{qo.paymentStatus}
AND so.shipping_method = #{qo.shippingMethod}
AND so.shipping_route = #{qo.shippingRoute}
AND so.target_region_id = #{qo.targetRegionId}
AND so.shipping_date >= #{qo.shippingDateStart}
AND so.shipping_date <= #{qo.shippingDateEnd}
AND EXISTS ( SELECT 1 FROM wms_shipping_order_item soi WHERE soi.shipping_order_id = so.id AND soi.sku_code LIKE CONCAT('%', #{qo.skuCode}, '%') )
ORDER BY so.create_time DESC

SELECT DISTINCT soi.shipping_order_id AS shippingOrderId, po.order_no AS purchaseOrderNo FROM wms_shipping_order_item soi INNER JOIN wms_purchase_order po ON soi.purchase_order_id = po.id WHERE soi.shipping_order_id IN
#{id}
ORDER BY soi.shipping_order_id, po.order_no

SELECT * FROM wms_shipping_order WHERE shipping_no = #{shippingNo} AND deleted = 0
AND id != #{excludeId}
LIMIT 1

SELECT so.id, so.shipping_no, so.provider_id, so.shipping_date, so.estimated_arrival_date, CASE so.shipping_method WHEN 'GRAY' THEN '灰关' WHEN 'WHITE' THEN '白关' ELSE so.shipping_method END AS shipping_method_desc, CASE so.shipping_route WHEN 'EAST' THEN '东线' WHEN 'WEST' THEN '西线' WHEN 'RAIL' THEN '铁路' ELSE so.shipping_route END AS shipping_route_desc, so.package_count, so.total_weight, so.total_amount, so.total_amount_cny, CASE so.payment_status WHEN 0 THEN '未付' WHEN 1 THEN '已付' ELSE '' END AS payment_status_desc, CASE so.shipping_status WHEN 'PENDING' THEN '待发货' WHEN 'SHIPPED' THEN '已发货' WHEN 'PARTIAL_ARRIVED' THEN '部分到货' WHEN 'ALL_ARRIVED' THEN '全部到货' WHEN 'COMPLETED' THEN '已完成' ELSE so.shipping_status END AS shipping_status_desc, so.create_time FROM wms_shipping_order so
so.deleted = 0
AND so.shipping_no LIKE CONCAT('%', #{qo.shippingNo}, '%')
AND so.provider_id = #{qo.providerId}
AND so.shipping_status = #{qo.shippingStatus}
AND so.payment_status = #{qo.paymentStatus}
AND so.shipping_method = #{qo.shippingMethod}
AND so.shipping_route = #{qo.shippingRoute}
AND so.shipping_date >= #{qo.shippingDateStart}
AND so.shipping_date <= #{qo.shippingDateEnd}
AND EXISTS ( SELECT 1 FROM wms_shipping_order_item soi WHERE soi.shipping_order_id = so.id AND soi.sku_code LIKE CONCAT('%', #{qo.skuCode}, '%') )
ORDER BY so.create_time DESC

SELECT so.target_region_id AS regionId, soi.sku_code AS skuCode, COALESCE(SUM(soi.quantity - soi.received_quantity), 0) AS quantity FROM wms_shipping_order so INNER JOIN wms_shipping_order_item soi ON so.id = soi.shipping_order_id WHERE so.deleted = 0 AND so.target_region_id IN
#{rid}
AND soi.sku_code IN
#{code}
AND so.shipping_status IN
#{status}
GROUP BY so.target_region_id, soi.sku_code HAVING quantity > 0

SELECT so.id AS shippingOrderId, so.shipping_no AS shippingNo, so.estimated_arrival_date AS estimatedArrivalDate, (soi.quantity - soi.received_quantity) AS quantity FROM wms_shipping_order so INNER JOIN wms_shipping_order_item soi ON so.id = soi.shipping_order_id WHERE so.deleted = 0 AND so.target_region_id = #{regionId} AND soi.sku_code = #{skuCode} AND so.shipping_status IN
#{status}
AND soi.quantity > soi.received_quantity ORDER BY so.estimated_arrival_date ASC
